"""Deterministic local mock implementation of the explanation provider contract."""

from __future__ import annotations

from model_health_assistant.ai_models import (
    AIExplanationRequest,
    AIExplanationResponse,
    AIWarningContext,
    AIWarningExplanation,
)
from model_health_assistant.ai_provider import AIRequestRejectedError

LOCAL_MOCK_PROVIDER_IDENTIFIER = "local-mock"
LOCAL_MOCK_PROVIDER_DISPLAY_NAME = "Local Mock Provider"
LOCAL_MOCK_LIMITATION = (
    "This is a deterministic local mock explanation used to verify the integration "
    "architecture. It is not generated by an AI model."
)

_RULE_REVIEW_STEPS: dict[str, tuple[str, ...]] = {
    "confirmed_recompute_error": (
        "Inspect the affected feature and the recorded FreeCAD error details.",
        "Review the feature tree from the earliest failing feature forward.",
        "After any manual correction, recompute the document and confirm the error state.",
    ),
    "sketch_generated_geometry_support": (
        "Open the sketch attachment settings and verify the recorded support reference.",
        "Review whether an origin plane, datum plane, or other stable reference fits the design intent.",
        "If changed manually, recompute and inspect downstream features.",
    ),
    "underdefined_sketch": (
        "Open the affected sketch and inspect its solver and constraint status.",
        "Confirm that any added constraints reflect the intended degrees of freedom.",
        "Recompute and review dependent features after manual edits.",
    ),
    "early_finishing_feature": (
        "Inspect the recorded downstream dependents of the finishing feature.",
        "Review whether the operation must occur at its current feature-tree position.",
        "If reordered manually, recompute and verify all affected downstream features.",
    ),
    "high_downstream_dependency_count": (
        "Review the feature's direct downstream dependents before making changes.",
        "Confirm that important references and design intent are documented and stable.",
    ),
    "unknown_sketch_support": (
        "Open the sketch attachment settings and identify its actual support manually.",
        "Confirm whether the support is stable before changing upstream features.",
    ),
    "hardcoded_repeated_dimensions": (
        "Review the affected feature's dimensions and expressions manually.",
        "Confirm whether shared parameters would better represent the design intent.",
    ),
}


class LocalMockAIProvider:
    """Local deterministic provider used only to verify integration plumbing."""

    @property
    def provider_identifier(self) -> str:
        return LOCAL_MOCK_PROVIDER_IDENTIFIER

    @property
    def display_name(self) -> str:
        return LOCAL_MOCK_PROVIDER_DISPLAY_NAME

    def is_available(self) -> bool:
        return True

    def capability_description(self) -> str:
        return (
            "Maps existing structured warnings to deterministic local test "
            "explanations without an AI model or network service."
        )

    def explain(self, request: AIExplanationRequest) -> AIExplanationResponse:
        """Return deterministic explanations for only the supplied warnings."""

        if not isinstance(request, AIExplanationRequest):
            raise AIRequestRejectedError(
                "Local Mock Provider requires an AIExplanationRequest."
            )

        warning_explanations = [
            self._explain_warning(warning) for warning in request.context.warnings
        ]
        warning_count = len(warning_explanations)
        if warning_count == 0:
            overall_summary = (
                "The deterministic local mock provider received no existing "
                "model-health warnings to explain. No AI model was used."
            )
        else:
            warning_label = "warning" if warning_count == 1 else "warnings"
            overall_summary = (
                f"The deterministic local mock provider mapped {warning_count} existing "
                f"model-health {warning_label}. It did not create new findings, inspect "
                "geometry, or use an AI model."
            )

        limitations = [
            LOCAL_MOCK_LIMITATION,
            (
                "The mock provider uses only the supplied structured context and "
                "does not independently verify warnings or inspect CAD geometry."
            ),
            "All review steps are advisory and require manual engineering judgment.",
        ]
        context_metadata = request.context.metadata
        if context_metadata.was_truncated:
            omitted_warning_phrase = (
                "1 warning was"
                if context_metadata.omitted_warning_count == 1
                else f"{context_metadata.omitted_warning_count} warnings were"
            )
            limitations.insert(
                0,
                (
                    "Deterministic context limits were applied before explanation: "
                    f"{context_metadata.included_warning_count} of "
                    f"{context_metadata.original_warning_count} warnings were included, "
                    f"{omitted_warning_phrase} omitted, and "
                    f"{context_metadata.truncated_field_count} fields were truncated."
                ),
            )

        return AIExplanationResponse(
            provider_identifier=self.provider_identifier,
            provider_display_name=self.display_name,
            overall_summary=overall_summary,
            warning_explanations=warning_explanations,
            limitations=limitations,
        )

    def _explain_warning(
        self,
        warning: AIWarningContext,
    ) -> AIWarningExplanation:
        feature_name = warning.affected_feature_internal_name or "the affected feature"
        rule_id = warning.rule_id or "unidentified_rule"
        severity = warning.severity or "unspecified"
        explanation = (
            "The deterministic source analysis states: "
            + (warning.technical_reason or warning.message or "No technical reason was supplied.")
        )
        why_it_matters = (
            f"The existing {severity}-severity warning applies rule '{rule_id}' to "
            f"feature '{feature_name}'. The source warning says: "
            + (warning.message or "No source warning message was supplied.")
        )
        manual_review_steps = list(
            _RULE_REVIEW_STEPS.get(
                warning.rule_id,
                (
                    f"Select feature '{feature_name}' and review the source warning and evidence.",
                    "Confirm the finding against the model's design intent before making manual changes.",
                    "Recompute and inspect affected features after any manual edit.",
                ),
            )
        )
        return AIWarningExplanation(
            warning_id=warning.warning_id,
            rule_id=warning.rule_id,
            affected_feature_internal_name=warning.affected_feature_internal_name,
            severity=warning.severity,
            explanation=explanation,
            why_it_matters=why_it_matters,
            manual_review_steps=manual_review_steps,
            confidence=(
                "Deterministic source mapping only; no independent assessment was performed."
            ),
            limitations=[
                "No CAD geometry was inspected by the local mock provider.",
                "This explanation does not add, verify, or replace the source warning.",
            ],
        )


__all__ = [
    "LOCAL_MOCK_LIMITATION",
    "LOCAL_MOCK_PROVIDER_DISPLAY_NAME",
    "LOCAL_MOCK_PROVIDER_IDENTIFIER",
    "LocalMockAIProvider",
]
